const NS='http://www.w3.org/2000/svg';
const paths=document.querySelector('#signal-paths');
let phase=.32,control=null,headline=null;
for(let i=0;i<36;i++){const p=document.createElementNS(NS,'path');p.setAttribute('fill','none');p.setAttribute('stroke',i%7===0?'#ff58c8':'#dfff00');p.setAttribute('stroke-width',i%7===0?'1.3':'.9');p.setAttribute('stroke-opacity',String(.35+i/70));paths.append(p)}
function draw(){for(let i=0;i<paths.children.length;i++){const rotation=i/36*Math.PI+phase*Math.PI;const points=[];for(let j=0;j<=100;j++){const t=j/100*Math.PI*2;const rx=174+Math.sin(i*.2+phase*6.28)*9;const ry=45+Math.sin(i*.14+phase*6.28)*23;const x=rx*Math.cos(t),y=ry*Math.sin(t);points.push(`${j?'L':'M'}${(250+x*Math.cos(rotation)-y*Math.sin(rotation)).toFixed(2)},${(250+x*Math.sin(rotation)+y*Math.cos(rotation)).toFixed(2)}`)}paths.children[i].setAttribute('d',points.join(' ')+'Z')}}
function stop(){control?.stop();control=null;document.querySelector('#run-signal').innerHTML='RUN SIGNAL <span aria-hidden="true">↻</span>';document.querySelector('#run-signal').setAttribute('aria-label','Replay signal animation')}
function play(){if(!window.PortfolioLab.motionEnabled()){stop();document.querySelector('#signal-status').textContent='A still signal. Motion is off in your preferences.';return}stop();if(!window.Motion)return;const start=phase;document.querySelector('#run-signal').innerHTML='PAUSE SIGNAL <span aria-hidden="true">Ⅱ</span>';document.querySelector('#run-signal').setAttribute('aria-label','Pause signal animation');control=window.Motion.animate(start,start+1,{duration:6,ease:'easeInOut',onUpdate:value=>{phase=value;draw()},onComplete:()=>{control=null;document.querySelector('#run-signal').innerHTML='RUN SIGNAL <span aria-hidden="true">↻</span>';document.querySelector('#run-signal').setAttribute('aria-label','Replay signal animation');document.querySelector('#signal-status').textContent='Study complete. Replay whenever you like.'}})}
draw();document.querySelector('#run-signal').addEventListener('click',()=>control?stop():play());
if(window.PortfolioLab.motionEnabled()){if(window.gsap){headline=window.gsap.timeline().fromTo('.hero-copy h1>span',{y:18,opacity:.7},{y:0,opacity:1,duration:.75,stagger:.085,ease:'power3.out'})}play()}
window.addEventListener('portfolio:motionchange',event=>{if(!event.detail.enabled){stop();headline?.progress(1);headline?.kill()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});window.addEventListener('pagehide',()=>{stop();headline?.kill()});
